// Ericka booking tools: ElevenLabs mid-call tool webhook -> booking RPCs.
// Design: docs/BOOKING.md.
//
// BEFORE ACTIVATING, replace the three placeholders below:
//   SUPABASE_URL  = https://phtmarvmovozydxipmat.supabase.co  (the CRM project)
//   SERVICE_KEY   = Supabase Dashboard -> Settings -> API Keys -> service_role (secret)
//                   Prefer an n8n credential over pasting it here; never export
//                   this workflow with the real key in it.
//   MIRROR_KEY    = same shared-secret convention as ghl-stage-sync; configure the
//                   ElevenLabs tool to send it as the X-Mirror-Key header.
//
// Response mode is "last node" on purpose: Ericka reads this JSON synchronously
// mid-call and only offers windows that come back in `open`.
//
// Body (JSON): { action, sub_account_id?, called_number?, caller_id?, ... }
//   action=check  -> { slot_date? (default: today, Phoenix), days? (default 7) }
//   action=book   -> { slot_date, window, customer_name, customer_phone?, lead_id? }
//   action=cancel -> { appointment_id }
//
// ElevenLabs tool setup (recommended): add these to the tool's body so the
// values come from the phone system, not from what the agent heard:
//   caller_id     = {{system__caller_id}}
//   called_number = {{system__called_number}}

const SUPABASE_URL = 'PASTE_PROJECT_URL_HERE';
const SERVICE_KEY = 'PASTE_SERVICE_ROLE_KEY_HERE';
const MIRROR_KEY = 'PASTE_SHARED_SECRET_HERE';

// Which tenant owns each dialed number (E.164, e.g. '+18882963752').
// When the dialed number is listed here it wins over any sub_account_id the
// agent sends, so a caller can never be booked into another tenant's calendar.
// Leave empty to keep the old behaviour (sub_account_id from the request).
const TENANT_BY_CALLED_NUMBER = {
  // '+18882963752': 'PASTE_ERICKA_AI_SUB_ACCOUNT_ID',
};

// Window hours in Phoenix time (24h). Windows overlap on purpose.
// A window for today is only offered while at least MIN_LEAD_MINUTES remain
// before it closes, so Ericka never offers a window that has already passed.
const WINDOW_HOURS = {
  morning: { start: 8, end: 12 },
  midday: { start: 12, end: 16 },
  late_afternoon: { start: 15, end: 18 },
};
const MIN_LEAD_MINUTES = 60;

const req = items[0].json;
const headersIn = req.headers ?? {};
const body = req.body ?? req;

if ((headersIn['x-mirror-key'] ?? '') !== MIRROR_KEY) {
  throw new Error('Rejected: bad X-Mirror-Key.');
}

const sbHeaders = (extra = {}) => ({
  apikey: SERVICE_KEY,
  Authorization: `Bearer ${SERVICE_KEY}`,
  'Content-Type': 'application/json',
  ...extra,
});

// One timezone: America/Phoenix (no DST). All dates are plain YYYY-MM-DD.
const phoenixToday = () =>
  new Date().toLocaleDateString('en-CA', { timeZone: 'America/Phoenix' });
const phoenixMinutesNow = () => {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/Phoenix', hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
  }).formatToParts(new Date());
  const get = (t) => Number(parts.find((p) => p.type === t).value);
  return get('hour') * 60 + get('minute');
};
const addDays = (iso, n) => {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10);
};
const stillBookable = (slotDate, window) => {
  const today = phoenixToday();
  if (slotDate > today) return true;
  if (slotDate < today) return false;
  const hours = WINDOW_HOURS[window];
  if (!hours) return false;
  return phoenixMinutesNow() <= hours.end * 60 - MIN_LEAD_MINUTES;
};
const digits = (s) => String(s ?? '').replace(/[^\d+]/g, '');

const action = String(body.action ?? '').toLowerCase();
const calledNumber = digits(body.called_number);
const subAccountId = TENANT_BY_CALLED_NUMBER[calledNumber] ?? body.sub_account_id;
if (!subAccountId) throw new Error('Missing sub_account_id.');

if (action === 'check') {
  const from = body.slot_date ?? phoenixToday();
  const days = Math.min(Math.max(parseInt(body.days ?? '7', 10) || 7, 1), 30);
  const rows = await this.helpers.httpRequest({
    method: 'GET',
    url:
      `${SUPABASE_URL}/rest/v1/booking_slots` +
      `?sub_account_id=eq.${encodeURIComponent(subAccountId)}` +
      `&slot_date=gte.${from}&slot_date=lte.${addDays(from, days)}` +
      `&order=slot_date.asc&select=slot_date,window,capacity,booked_count`,
    headers: sbHeaders(),
    json: true,
  });
  const open = (rows ?? [])
    .filter((r) => r.booked_count < r.capacity)
    .filter((r) => stillBookable(r.slot_date, r.window))
    .map((r) => ({ date: r.slot_date, window: r.window, spots: r.capacity - r.booked_count }));
  return [{ json: { open } }];
}

if (action === 'book') {
  if (!stillBookable(body.slot_date, body.window)) {
    return [{ json: { booked: false, reason: 'window_passed', slot_date: body.slot_date, window: body.window } }];
  }
  // Caller ID from the phone system beats whatever the agent heard.
  const phone = digits(body.caller_id) || digits(body.customer_phone);

  // Idempotency: a retried tool call (or a caller asking twice) must not book
  // a second job. If this caller already holds a booked appointment in the
  // same window, return it instead of booking again.
  if (phone) {
    const existing = await this.helpers.httpRequest({
      method: 'GET',
      url:
        `${SUPABASE_URL}/rest/v1/appointments` +
        `?sub_account_id=eq.${encodeURIComponent(subAccountId)}` +
        `&customer_phone=eq.${encodeURIComponent(phone)}&status=eq.booked` +
        `&select=appointment_id,booking_slots!inner(slot_date,window)` +
        `&booking_slots.slot_date=eq.${body.slot_date}` +
        `&booking_slots.window=eq.${encodeURIComponent(body.window)}&limit=1`,
      headers: sbHeaders(),
      json: true,
    });
    if (existing && existing.length) {
      return [{ json: { booked: true, already_booked: true, appointment_id: existing[0].appointment_id, slot_date: body.slot_date, window: body.window } }];
    }
  }

  // book_slot returns the new appointment_id, or NULL when the window filled
  // (or was never provisioned) between the check and this call.
  const appointmentId = await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/rest/v1/rpc/book_slot`,
    headers: sbHeaders(),
    body: {
      p_sub_account_id: subAccountId,
      p_slot_date: body.slot_date,
      p_window: body.window,
      p_customer_name: body.customer_name ?? 'Unknown caller',
      p_customer_phone: phone,
      p_lead_id: body.lead_id ?? null,
    },
    json: true,
  });
  if (!appointmentId) {
    return [{
      json: {
        booked: false,
        reason: 'window_full_or_missing',
        slot_date: body.slot_date,
        window: body.window,
      },
    }];
  }
  return [{ json: { booked: true, appointment_id: appointmentId, slot_date: body.slot_date, window: body.window } }];
}

if (action === 'cancel') {
  const cancelled = await this.helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/rest/v1/rpc/release_slot`,
    headers: sbHeaders(),
    body: { p_appointment_id: body.appointment_id },
    json: true,
  });
  return [{ json: { cancelled: cancelled === true } }];
}

throw new Error(`Unknown action: ${action}`);
